import{_ as n,C as t,o as e,c as d,a2 as r,j as i,E as s,a as o}from"./chunks/framework.C21TwvGF.js";const N=JSON.parse('{"title":"27-dars (Mentor). 27-dars: Flowalgorithmda takrorlanuvchi algoritmlar va sikllar bilan ishlash (1-dars)","description":"","frontmatter":{"title":"27-dars (Mentor). 27-dars: Flowalgorithmda takrorlanuvchi algoritmlar va sikllar bilan ishlash (1-dars)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":9,"link":"/mentor/8-sinf-cs/hafta-09/"},"g":27,"title":"27-dars: Flowalgorithmda takrorlanuvchi algoritmlar va sikllar bilan ishlash (1-dars)","lead":"Flowalgorithmda takrorlanuvchi algoritmlar va sikllar bilan ishlash (1-dars)","slide":"/slaydlar/8-sinf-cs/hafta-09/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-09/dars-3-test.html","student_link":"/8-sinf-cs/hafta-09/dars-3","tabs":[{"g":25,"link":"/mentor/8-sinf-cs/hafta-09/dars-1","current":false},{"g":26,"link":"/mentor/8-sinf-cs/hafta-09/dars-2","current":false},{"g":27,"link":"/mentor/8-sinf-cs/hafta-09/dars-3","current":true}],"prev":{"g":26,"title":"26-dars: Flowalgorithmda tarmoqlanuvchi algoritmlar va shartlar bilan ishlash (2-dars)","link":"/mentor/8-sinf-cs/hafta-09/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-09/dars-3.md","filePath":"mentor/8-sinf-cs/hafta-09/dars-3.md"}'),h={name:"mentor/8-sinf-cs/hafta-09/dars-3.md"},m={class:"blk"},u={id:"dars-rejasi",tabindex:"-1"},c={class:"blk"},g={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},p={class:"blk"},y={id:"tezkor-nazorat-savollari",tabindex:"-1"},b={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function v(_,a,S,T,z,x){const l=t("Icon");return e(),d("div",null,[a[15]||(a[15]=r("<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 9-hafta (3-dars)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Nazariy tushunchalar (25 daqiqa) + Flowgorithm sikllar amaliyoti (50 daqiqa) + Xulosa (5 daqiqa)</p><hr>",2)),i("div",m,[i("h2",u,[s(l,{name:"file-text"}),a[0]||(a[0]=o(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ol><li><strong>Tashkiliy qism va o&#39;tgan mavzuni takrorlash (10 daqiqa)</strong><ul><li>25 va 26-darslardagi tarmoqlanish, <code>Decision</code> va mantiqiy operatorlarni takrorlash.</li><li>Muammo: «Agar ekranga 100 marta &quot;Salom&quot; so&#39;zini chiqarish yoki 1 dan 1000 gacha sonlarni qo&#39;shish kerak bo&#39;lsa, 1000 ta blok chizamizmi?»</li></ul></li><li><strong>Yangi mavzu: Takrorlanuvchi algoritmlar va Sikl tushunchasi (25 daqiqa)</strong><ul><li>Sikl (Loop) nima? Hayotdagi davriy jarayonlar (soat mili, fasllar, yugurish davrasi).</li><li>Flowgorithmda sikl bloklari bilan tanishuv: <ul><li><code>For</code> (Parametrli / Aniq takrorlanishli sikl)</li><li><code>While</code> (Old shartli sikl)</li></ul></li><li>Siklning asosiy tarkibiy qismlari: <ul><li><em>Hisoblagich o&#39;zgaruvchi (Counter / <code>i</code>)</em></li><li><em>Boshlang&#39;ich qiymat (Start)</em></li><li><em>Tugash qiymati / Shart (End / Condition)</em></li><li><em>Qadam (Step, odatda +1)</em></li><li><em>Sikl tanasi (Body of Loop)</em></li></ul></li><li>1 dan N gacha bo&#39;lgan sonlar ketma-ketligi va yig&#39;indisini hisoblash mantig&#39;i.</li></ul></li><li><strong>Amaliy laboratoriya mashg&#39;uloti: Flowgorithmda birinchi sikllar (40 daqiqa)</strong><ul><li>1-loyiha: Ekranga 10 marta «Dasturlashni o&#39;rganamiz!» deb chiqarish.</li><li>2-loyiha: 1 dan N gacha bo&#39;lgan sonlarni chiqarish (<code>For</code> bloki).</li><li>3-loyiha: 1 dan N gacha bo&#39;lgan sonlar yig&#39;indisini hisoblash (<code>sum = sum + i</code>).</li><li>4-loyiha: F6 (Step) yordamida siklning qanday aylanayotganini va hisoblagich qanday o&#39;sayotganini ko&#39;z bilan kuzatish.</li></ul></li><li><strong>Darsni yakunlash va baholash (5 daqiqa)</strong><ul><li>Tezkor nazorat savollari.</li><li>Uyga vazifani tushuntirish.</li></ul></li></ol><hr>",2))]),i("div",c,[i("h2",g,[s(l,{name:"file-text"}),a[3]||(a[3]=o(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-sikl-loop-takrorlanuvchi-algoritm-nima" tabindex="-1">1. Sikl (Loop / Takrorlanuvchi algoritm) nima? <a class="header-anchor" href="#_1-sikl-loop-takrorlanuvchi-algoritm-nima" aria-label="Permalink to &quot;1. Sikl (Loop / Takrorlanuvchi algoritm) nima?&quot;">​</a></h3><ul><li><strong>Ta&#39;rif:</strong> Ma&#39;lum bir shart bajarilgunga qadar ma&#39;lum bir buyruqlar guruhining qayta-qayta takrorlanishiga <strong>takrorlanuvchi algoritm (sikl)</strong> deyiladi.</li><li><strong>Siklning kuchi:</strong> Dasturchi atigi 3 ta blok yozib, kompyuterga 1 million marta takrorlanadigan ulkan hisob-kitobni buyura oladi.</li><li><strong>Cheksiz sikl (Infinite Loop) xavfi:</strong> Agar sikldan chiqish sharti noto&#39;g&#39;ri qo&#39;yilsa, sikl to&#39;xtamay cheksiz aylanib, dasturni qotirib qo&#39;yishi mumkin.</li></ul><h3 id="_2-for-sikli-parametrli-sikl" tabindex="-1">2. For sikli (Parametrli sikl) <a class="header-anchor" href="#_2-for-sikli-parametrli-sikl" aria-label="Permalink to &quot;2. For sikli (Parametrli sikl)&quot;">​</a></h3><p>Takrorlanishlar soni oldindan aniq ma&#39;lum bo&#39;lganda (masalan, 10 marta, 50 marta yoki 1 dan $N$ gacha) <code>For</code> bloki eng qulay hisoblanadi.</p><ul><li>Blok shakli: Oltiburchak (Hexagon) shaklidagi blok.</li><li>Parametrlari: <ul><li><em>Variable:</em> Hisoblagich nomi (masalan, <code>i</code>).</li><li><em>Start Value:</em> Boshlang&#39;ich son (masalan, <code>1</code>).</li><li><em>End Value:</em> Tugash soni (masalan, <code>N</code>).</li><li><em>Direction:</em> O&#39;sish (<code>Increasing</code>) yoki Kamayish (<code>Decreasing</code>).</li><li><em>Step:</em> Qadam kattaligi (masalan, <code>1</code>).</li></ul></li></ul><h3 id="_3-yig-indi-yig-ish-mantig-i-sum-sum-i" tabindex="-1">3. Yig&#39;indi yig&#39;ish mantig&#39;i (<code>sum = sum + i</code>) <a class="header-anchor" href="#_3-yig-indi-yig-ish-mantig-i-sum-sum-i" aria-label="Permalink to &quot;3. Yig&#39;indi yig&#39;ish mantig&#39;i (`sum = sum + i`)&quot;">​</a></h3><p>Dasturlashda sonlarni qo&#39;shib borish uchun <strong>akkumulyator (yig&#39;uvchi)</strong> o&#39;zgaruvchi ishlatiladi:</p><ol><li>Boshida <code>sum = 0</code> deb olinadi.</li><li>Sikl har aylanganda yangi son qo&#39;shiladi: <code>sum = sum + i</code>.</li><li>Sikl to&#39;xtagach, yakuniy natija <code>sum</code> ekranga chiqariladi.</li></ol><hr>',9))]),i("div",k,[i("h2",q,[s(l,{name:"file-text"}),a[6]||(a[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-salomlashishni-5-marta-takrorlash-·-oson" tabindex="-1">1-topshiriq: Salomlashishni 5 marta takrorlash · oson <a class="header-anchor" href="#_1-topshiriq-salomlashishni-5-marta-takrorlash-·-oson" aria-label="Permalink to &quot;1-topshiriq: Salomlashishni 5 marta takrorlash · oson&quot;">​</a></h3><p>Konsolga 5 marta <code>&quot;Salom, dunyo!&quot;</code> so&#39;zini chiqaruvchi For siklini tuzing.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer i</code></li><li><code>For i = 1 to 5 step 1</code><ul><li>Sikl tanasi: <code>Output &quot;Salom, dunyo!&quot;</code></li></ul></li><li>Sikldan keyin: <code>Output &quot;Dastur tugadi&quot;</code></li></ol><hr><h3 id="_2-topshiriq-1-dan-n-gacha-sonlarni-chiqarish-·-oson" tabindex="-1">2-topshiriq: 1 dan N gacha sonlarni chiqarish · oson <a class="header-anchor" href="#_2-topshiriq-1-dan-n-gacha-sonlarni-chiqarish-·-oson" aria-label="Permalink to &quot;2-topshiriq: 1 dan N gacha sonlarni chiqarish · oson&quot;">​</a></h3><p>Foydalanuvchi $N$ sonini kiritadi. Dastur 1 dan $N$ gacha bo&#39;lgan barcha sonlarni ketma-ket chiqarsin.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer n, i</code></li><li><code>Output &quot;N sonini kiriting:&quot;</code></li><li><code>Input n</code></li><li><code>For i = 1 to n step 1</code><ul><li>Sikl tanasi: <code>Output i</code></li></ul></li></ol><hr><h3 id="_3-topshiriq-1-dan-n-gacha-sonlar-yig-indisi-·-o-rta" tabindex="-1">3-topshiriq: 1 dan N gacha sonlar yig&#39;indisi · o&#39;rta <a class="header-anchor" href="#_3-topshiriq-1-dan-n-gacha-sonlar-yig-indisi-·-o-rta" aria-label="Permalink to &quot;3-topshiriq: 1 dan N gacha sonlar yig&#39;indisi · o&#39;rta&quot;">​</a></h3><p>Foydalanuvchi $N$ sonini kiritadi. 1 dan $N$ gacha bo&#39;lgan barcha sonlar yig&#39;indisini ($1 + 2 + 3 + ... + N$) hisoblab beruvchi dastur tuzing.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer n, i, sum</code></li><li><code>Assign sum = 0</code></li><li><code>Output &quot;N sonini kiriting:&quot;</code></li><li><code>Input n</code></li><li><code>For i = 1 to n step 1</code><ul><li><code>Assign sum = sum + i</code></li></ul></li><li><code>Output &quot;1 dan &quot; &amp; n &amp; &quot; gacha sonlar yig&#39;indisi: &quot; &amp; sum</code></li></ol><hr><h3 id="_4-topshiriq-juft-sonlarni-chiqarish-qadam-2-·-o-rta" tabindex="-1">4-topshiriq: Juft sonlarni chiqarish (Qadam = 2) · o&#39;rta <a class="header-anchor" href="#_4-topshiriq-juft-sonlarni-chiqarish-qadam-2-·-o-rta" aria-label="Permalink to &quot;4-topshiriq: Juft sonlarni chiqarish (Qadam = 2) · o&#39;rta&quot;">​</a></h3><p>1 dan 20 gacha bo&#39;lgan barcha juft sonlarni (2, 4, 6, ..., 20) ekranga chiqaruvchi For siklini tuzing.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer i</code></li><li><code>For i = 2 to 20 step 2</code><ul><li><code>Output i</code></li></ul></li></ol><hr><h3 id="_5-topshiriq-ko-paytirish-jadvali-karat-jadvali-·-qiyin" tabindex="-1">5-topshiriq: Ko&#39;paytirish jadvali (Karat jadvali) · qiyin <a class="header-anchor" href="#_5-topshiriq-ko-paytirish-jadvali-karat-jadvali-·-qiyin" aria-label="Permalink to &quot;5-topshiriq: Ko&#39;paytirish jadvali (Karat jadvali) · qiyin&quot;">​</a></h3><p>Foydalanuvchi bitta son kiritadi (masalan, 7). Dastur ushbu sonning 1 dan 10 gacha bo&#39;lgan ko&#39;paytirish jadvalini chiqarsin (masalan: <code>7 * 1 = 7</code>, <code>7 * 2 = 14</code>, ..., <code>7 * 10 = 70</code>).</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer son, i, natija</code></li><li><code>Output &quot;Qaysi sonning karra jadvali kerak?&quot;</code></li><li><code>Input son</code></li><li><code>For i = 1 to 10 step 1</code><ul><li><code>Assign natija = son * i</code></li><li><code>Output son &amp; &quot; * &quot; &amp; i &amp; &quot; = &quot; &amp; natija</code></li></ul></li></ol><hr>',25))]),i("div",p,[i("h2",y,[s(l,{name:"file-text"}),a[9]||(a[9]=o(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Sikl deb nimaga aytiladi va dasturlashda nima uchun kerak?</li><li><code>For</code> siklining asosiy qismlari qaysilar?</li><li>Hisoblagich o&#39;zgaruvchi (odatda <code>i</code>) nima vazifani bajaradi?</li><li>Nima uchun yig&#39;indi hisoblashda boshlang&#39;ich qiymat <code>sum = 0</code> deb olinadi?</li><li>Cheksiz sikl nima va undan qanday saqlanish mumkin?</li></ol><hr>",2))]),i("div",b,[i("h2",f,[s(l,{name:"house"}),a[12]||(a[12]=o(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("ol",null,[i("li",null,"Uyga vazifa faylidagi 27-dars topshirig'ini bajarish."),i("li",null,[o("Foydalanuvchi kiritgan sonning faktorialini ($N! = 1 \\times 2 \\times ... \\times N$) hisoblovchi blok-sxema loyihasini yaratish (Eslatma: ko'paytmada boshlang'ich qiymat "),i("code",null,"kopaytma = 1"),o(" olinadi).")]),i("li",null,"9-hafta yakuniy test savollariga tayyorgarlik ko'rish.")],-1))])])}const P=n(h,[["render",v]]);export{N as __pageData,P as default};
